-- Dungeon Master's Guide II source-backed rules catalog.
-- Mechanical summaries are intentionally concise; the supplied sourcebook remains authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dmg2-3.5','dungeon-masters-guide-ii-3-5','Dungeon Master''s Guide II','DMG II',
        'Wizards of the Coast','dnd','3.5','D&D v.3.5 Dungeon Master''s Guide II: expanded DM procedures, encounter subsystems, campaign tools, character teamwork systems, and magic-item options.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,summary,tags,mechanics) AS (VALUES
  ('dmg2-apprenticeship','Apprenticeship','175','characters','subsystem',1,0,NULL,NULL,'An apprentice studies under a master, exchanging time, obligations, and training for campaign benefits and access determined by the apprenticeship rules.','["training","apprentice"]','{}'),
  ('dmg2-mentorship','Mentorship','179','characters','subsystem',1,0,NULL,NULL,'Mentorship creates an ongoing teacher-student relationship with requirements and benefits based on continued instruction and roleplaying.','["training","mentor"]','{}'),
  ('dmg2-running-business','Running a Business','180','economy','subsystem',1,0,NULL,NULL,'A PC-owned business operates in terms; each term produces a profit check modified by business characteristics, events, and owner decisions, producing profit or loss.','["business","economy"]','{}'),
  ('dmg2-business-events','Business Events','184','economy','table',1,0,'dmg2-running-business',NULL,'Periodic business events can modify profit checks or create encounters; examples include sabotage, spectacles, tax changes, unusual patrons, and threats.','["business","events"]','{}'),
  ('dmg2-business-sabotage','Business Event: Sabotage','188','economy','rule',1,0,'dmg2-business-events',NULL,'Resolve sabotage with a special profit check opposed by the saboteur''s Disable Device check; failure imposes a -4 penalty on the term''s profit check.','["business"]','{"profit_check_penalty":-4}'),
  ('dmg2-business-spectacle','Business Event: Spectacle','188','economy','rule',1,0,'dmg2-business-events',NULL,'A nearby spectacle that draws customers grants +2 on the term''s profit check.','["business"]','{"profit_check_bonus":2}'),
  ('dmg2-business-unexpected-taxes','Business Event: Unexpected Taxes','188','economy','rule',1,0,'dmg2-business-events',NULL,'Unexpected taxes impose a -1d4 penalty on profit checks for 1d6 terms.','["business"]','{"penalty":"1d4","duration_terms":"1d6"}'),
  ('dmg2-business-unusual-patron','Business Event: Unusual Patron','188','economy','rule',1,0,'dmg2-business-events',NULL,'A continuing unusual patron grants a permanent +1 profit-check bonus while that patron continues supporting the business.','["business"]','{"profit_check_bonus":1,"duration":"while patron remains"}'),
  ('dmg2-teamwork-benefits','Teamwork Benefits','189','characters','subsystem',1,0,NULL,NULL,'A trained team gains special benefits based on task-leader and member prerequisites, lowest member Hit Dice, and continued ability to communicate.','["teamwork"]','{}'),
  ('dmg2-team-training','Teamwork Training and Roster','190','characters','rule',1,0,'dmg2-teamwork-benefits',NULL,'A team must train together for at least two weeks. Team membership and benefit prerequisites are tracked on a roster.','["teamwork","training"]','{"training_weeks":2}'),
  ('dmg2-team-benefit-rate','Teamwork Benefit Progression','189','characters','rule',1,0,'dmg2-teamwork-benefits',NULL,'A team gains one teamwork benefit for every 4 Hit Dice of its lowest-level member. When gaining a new benefit, it may swap out one previously known benefit for another qualified choice.','["teamwork"]','{"hit_dice_per_benefit":4}'),
  ('dmg2-team-communication','Teamwork Communication','190','characters','rule',1,0,'dmg2-teamwork-benefits',NULL,'Unless a benefit says otherwise, it functions only when team members can communicate verbally, by gesture, or magically.','["teamwork","communication"]','{}'),
  ('dmg2-teamwork-animal-trick','Teamwork Trick for Animals','189','characters','rule',1,0,'dmg2-teamwork-benefits',NULL,'An Intelligence 1-2 creature can join a team only after learning the teamwork trick; teaching it requires DC 20 Handle Animal and it must still meet team-member prerequisites.','["teamwork","animals"]','{"handle_animal_dc":20,"min_int":1,"max_int":2}'),
  ('dmg2-companion-spirits','Companion Spirits','194','characters','subsystem',1,0,NULL,NULL,'A group can bind one companion spirit that grants teamwide tiered magical benefits and improves as the lowest-level member advances.','["companion-spirit","teamwork"]','{}'),
  ('dmg2-companion-spirit-acquisition','Acquiring a Companion Spirit','194','characters','procedure',1,0,'dmg2-companion-spirits',NULL,'Two to eight creatures, each at least 4 HD and Intelligence 3+, perform a 1-hour ritual with DC 15 Spellcraft, 300 gp reagents per member, and 300 XP from each member; taking 10 is allowed and failure wastes the hour.','["companion-spirit","ritual"]','{"min_members":2,"max_members":8,"min_hd":4,"min_int":3,"ritual_hours":1,"spellcraft_dc":15,"reagent_gp_per_member":300,"xp_per_member":300,"take_10":true}'),
  ('dmg2-companion-spirit-limit','Companion Spirit Connection Limit','195','characters','rule',1,0,'dmg2-companion-spirits',NULL,'A creature cannot be connected to more than one companion spirit at a time.','["companion-spirit"]','{"max_companion_spirits_per_creature":1}'),
  ('dmg2-companion-spirit-use','Using Companion Spirit Benefits','195','characters','rule',1,0,'dmg2-companion-spirits',NULL,'Unless a benefit says otherwise, using a companion-spirit benefit is a free action usable once per team member''s turn and has no visible or audible manifestation unless stated.','["companion-spirit"]','{"default_action":"free","uses_per_member_turn":1}'),
  ('dmg2-companion-spirit-join','Joining a Companion Spirit Team','195','characters','procedure',1,0,'dmg2-companion-spirits',NULL,'If fewer than eight members are connected, a new member can join by repeating the ritual at the team''s highest tier; only the joining member pays XP, while reagent cost is based on total team membership.','["companion-spirit"]','{}'),
  ('dmg2-companion-spirit-leave','Leaving a Companion Spirit Team','195','characters','procedure',1,0,'dmg2-companion-spirits',NULL,'Disconnect by meditating for 1 hour and burning 50 gp of the attracting reagents in reverse order; no Spellcraft check is required.','["companion-spirit"]','{"hours":1,"reagent_gp":50,"check_required":false}'),
  ('dmg2-companion-spirit-advancement','Improving a Companion Spirit','195','characters','rule',1,0,'dmg2-companion-spirits',NULL,'Starting when the lowest-level team member reaches 7 HD, the team can improve the spirit each time that lowest-level member gains 3 additional HD.','["companion-spirit"]','{"first_tier_hd":7,"hd_per_additional_tier":3}'),
  ('dmg2-prestige-class-design','Designing Prestige Classes','203','design','guidance',0,1,NULL,NULL,'A prestige class should have a clear concept, meaningful prerequisites, an appropriate chassis, and abilities balanced against opportunity cost and entry timing.','["prestige-class","design"]','{}'),
  ('dmg2-pc-organizations','PC Organizations','210','campaign','subsystem',1,0,NULL,NULL,'Player-created organizations can have membership, goals, resources, benefits, headquarters, rivals, and advancement tied to campaign actions.','["organizations"]','{}'),
  ('dmg2-guilds','Guilds','223','campaign','subsystem',1,0,'dmg2-pc-organizations',NULL,'Guild rules model membership, benefits, duties, rank, resources, and organization-level adventure hooks.','["guilds"]','{}'),
  ('dmg2-magic-item-signature-traits','Magic Item Signature Traits','229','magic-items','subsystem',1,0,NULL,NULL,'A magic item can possess a signature trait that gives it distinctive behavior or presentation and can be learned, identified, and assigned using the subsystem.','["magic-items","signature-traits"]','{}'),
  ('dmg2-bonded-magic-items','Bonded Magic Items','231','magic-items','subsystem',1,0,NULL,NULL,'A character can form a bond with a chosen magic item through bonding rituals, adding magical properties and granting a temporary ritual-specific character benefit.','["magic-items","bonding"]','{}'),
  ('dmg2-bonding-ritual','Bonding Ritual Procedure','232','magic-items','procedure',1,0,'dmg2-bonded-magic-items',NULL,'A bonding ritual combines a task and ceremony. The bonding character must personally complete the task and personally pay any XP cost, though others can assist or contribute gp where permitted.','["magic-items","ritual"]','{}'),
  ('dmg2-multiple-bonding-rituals','Multiple Bonding Rituals','232','magic-items','rule',1,0,'dmg2-bonded-magic-items',NULL,'Multiple rituals can be completed for one item. Magical properties from prior rituals remain, but the character benefit from the newest ritual replaces the previous ritual''s character benefit, including applicable Truebond benefit.','["magic-items","ritual"]','{}'),
  ('dmg2-magical-locations-treasure','Magical Locations as Treasure','235','treasure','subsystem',1,0,NULL,NULL,'A magical location can grant a character a defined benefit after discovery and interaction; its treasure value is accounted for like other character wealth.','["magical-locations","treasure"]','{}'),
  ('dmg2-synergy-armor-abilities','Synergy Armor and Shield Abilities','250','magic-items','subsystem',1,0,NULL,NULL,'A synergy special ability becomes available only when an item already has the required prerequisite magical property or properties.','["magic-items","synergy"]','{}'),
  ('dmg2-synergy-weapon-abilities','Synergy Weapon Abilities','253','magic-items','subsystem',1,0,NULL,NULL,'Weapon synergy abilities require an existing prerequisite special ability and add their own effective enhancement value/cost.','["magic-items","synergy"]','{}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dmg2-3.5-rule-' || d.slug, 'dmg2-3.5', d.source_page, d.slug, d.name, d.summary, d.summary,
  0,NULL,1,d.category,d.kind,d.is_variant,d.default_enabled,d.parent_slug,d.supersedes_slug,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r
  WHERE r.slug=d.slug AND r.owner_user_id IS NULL
);
